package com.deepanshuraj.opspilot.agent; import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean; import org.springframework.stereotype.Component;
@Component @ConditionalOnMissingBean(name="llmClient") public class TemplateLlmClient implements LlmClient {public String provider(){return "template (offline, deterministic)";}public String complete(String system,String prompt){StringBuilder obs=new StringBuilder(),ctx=new StringBuilder();String section="";String q="";for(String line:prompt.split("\\n")){if(line.startsWith("QUESTION:")){q=line.substring(9).trim();section="";}else if(line.equalsIgnoreCase("OBSERVATIONS:"))section="o";else if(line.equalsIgnoreCase("RETRIEVED CONTEXT:"))section="c";else if(line.equalsIgnoreCase("CONVERSATION:"))section="x";else if(!line.isBlank()&&section.equals("o"))obs.append(line.startsWith("-")?line:"- "+line).append('\n');else if(!line.isBlank()&&section.equals("c"))ctx.append(line).append(' ');}if(obs.isEmpty()&&ctx.isEmpty())return "I could not find order data or runbook guidance for \""+q+"\".";String out=obs.isEmpty()?"":"Here is what I found:\n"+obs;if(!ctx.isEmpty())out+="Recommended next steps (from runbooks):\n- "+ctx.toString().replaceAll("\\s+"," ").trim();return out.strip();}}
